<script setup>
import {ref,computed,onMounted} from 'vue';
import {ArrowLeft,ArrowRight,Check,ShieldCheck,Clock3,ChevronRight,UserRound,AlertCircle} from 'lucide-vue-next';
import {api} from './api';
const config=ref(null),user=ref(null),token=ref(sessionStorage.getItem('preview-token') || ''),survey=ref(null),completion=ref(null),answers=ref({}),consent=ref(false),nickname=ref(''),busy=ref(false),error=ref(''),view=ref('bind'),privacy=ref(false),avatarFile=ref(null),localAvatar=ref('');
const progress=computed(()=>survey.value?survey.value.questions.filter(q=>hasAnswer(answers.value[q.id])).length:0);
const authHeaders=()=>({Authorization:`Bearer ${token.value}`});
const hasAnswer=a=>Array.isArray(a)?a.length>0:typeof a==='string' && a.trim().length>0;
async function run(fn){busy.value=true;error.value='';try{await fn();}catch(e){error.value=e.message;if(e.status===401){token.value='';sessionStorage.removeItem('preview-token');view.value='bind';}}finally{busy.value=false;}}
async function enter(){const data=await api('/surveys/current',{headers:authHeaders()});survey.value=data.survey;if(data.response){completion.value=data.response.completion;view.value='success';}else{const saved=JSON.parse(localStorage.getItem(`draft-${survey.value.id}`) || 'null');answers.value=saved?.version===survey.value.version?saved.answers:{};await api(`/surveys/${survey.value.id}/start`,{method:'POST',headers:authHeaders()});view.value='survey';}}
async function bind(){if(!consent.value){error.value='请先阅读并同意隐私说明';return;}await run(async()=>{if(!config.value?.devLogin)throw new Error('网页仅供本地验收，正式参与请使用微信小程序');let deviceId=localStorage.getItem('preview-device');if(!deviceId){deviceId=crypto.randomUUID();localStorage.setItem('preview-device',deviceId);}if(!token.value){const data=await api('/auth/dev',{method:'POST',body:{deviceId}});token.value=data.token;sessionStorage.setItem('preview-token',data.token);}if(avatarFile.value){const body=new FormData();body.append('avatar',avatarFile.value);await api('/me/avatar',{method:'POST',headers:authHeaders(),body});}user.value=await api('/me/bind',{method:'POST',headers:authHeaders(),body:{nickname:nickname.value,consentVersion:config.value.privacyVersion}});await enter();});}
function saveDraft(){localStorage.setItem(`draft-${survey.value.id}`,JSON.stringify({version:survey.value.version,answers:answers.value}));}
function select(q,id){if(q.type==='single')answers.value[q.id]=id;else{const selected=answers.value[q.id] || [];answers.value[q.id]=selected.includes(id)?selected.filter(x=>x!==id):[...selected,id];}saveDraft();}
function isSelected(q,id){const a=answers.value[q.id];return Array.isArray(a)?a.includes(id):a===id;}
async function submit(){const missing=survey.value.questions.find(q=>q.required&&!hasAnswer(answers.value[q.id]));if(missing){error.value='请完成所有必填题目';document.getElementById(missing.id)?.scrollIntoView({block:'center',behavior:'smooth'});document.getElementById(missing.id)?.querySelector('input,textarea')?.focus();return;}const phone=survey.value.questions.find(q=>q.type==='phone');if(!phone || !/^1[3-9]\d{9}$/.test(answers.value[phone.id] || '')){error.value='请填写正确的 11 位中国大陆手机号';document.getElementById(phone?.id)?.scrollIntoView({block:'center'});return;}await run(async()=>{const data=await api(`/surveys/${survey.value.id}/responses`,{method:'POST',headers:authHeaders(),body:{version:survey.value.version,answers:answers.value}});completion.value=data.completion;localStorage.removeItem(`draft-${survey.value.id}`);view.value='success';window.scrollTo(0,0);});}
function avatarChanged(event){const file=event.target.files[0];if(!file)return;if(file.size>3*1024*1024){error.value='头像不能超过 3MB';return;}if(localAvatar.value)URL.revokeObjectURL(localAvatar.value);avatarFile.value=file;localAvatar.value=URL.createObjectURL(file);}
onMounted(()=>run(async()=>{config.value=await api('/config');if(token.value){user.value=await api('/me',{headers:authHeaders()});nickname.value=user.value.nickname;if(user.value.bound)await enter();}}));
</script>
<template>
  <div class="preview-shell"><div class="preview-toolbar"><a href="/admin/"><ArrowLeft :size="15"/>管理后台</a><span>小程序设计预览</span><span class="preview-size">375 × 自适应</span></div><div v-if="config?.devLogin" class="dev-notice">本地体验环境 · 体验身份仅供验收</div>
    <main class="phone-preview" :class="{'success-preview':view==='success'}">
      <template v-if="view==='bind'"><img class="survey-header" src="/assets/survey-header.png" alt="华堂宁®（多格列艾汀）知多少"/><section class="bind-card"><span class="bind-icon"><ShieldCheck :size="27"/></span><span class="eyebrow">HUATANGNING SURVEY</span><h1>欢迎参与问卷调查</h1><p>绑定微信后，即可开始填写。<br>感谢您分享宝贵的见解。</p><form @submit.prevent="bind"><label class="avatar-upload"><img v-if="localAvatar" :src="localAvatar" alt="选中的头像"/><UserRound v-else :size="25"/><span>选择头像（可选）</span><input type="file" accept="image/jpeg,image/png" @change="avatarChanged"/></label><label class="bind-nickname">您的昵称<input v-model="nickname" autocomplete="nickname" maxlength="30" placeholder="请输入昵称" required/></label><label class="consent"><input v-model="consent" type="checkbox"/><span>我已阅读并同意<button class="inline-link" type="button" @click="privacy=true">《隐私说明》</button>，授权用于本次问卷。</span></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="psd-button" :disabled="busy || !config?.devLogin">{{busy?'正在绑定…':config?.devLogin?'体验绑定并开始':'请通过微信小程序参与'}}<ArrowRight :size="18"/></button><p class="bind-note">{{config?.devLogin?'当前为本地体验身份，不会获取真实微信信息。':'微信身份需在小程序内授权获取。'}}</p></form></section><img class="survey-footer" src="/assets/survey-footer.jpg" alt=""/></template>
      <template v-else-if="view==='survey' && survey"><img v-if="survey.title==='华堂宁® (多格列艾汀)知多少'" class="survey-header" src="/assets/survey-header.png" :alt="survey.title"/><header v-else class="custom-survey-header"><img src="/assets/brand-strip.png" alt="华领医药 华堂宁"/><h1>{{survey.title}}</h1></header><form class="psd-survey" @submit.prevent="submit"><fieldset v-for="(q,i) in survey.questions" :key="q.id" :id="q.id" class="psd-question"><legend>{{i+1}}. {{q.title}}<small v-if="q.type==='multiple'">（多选）</small><small v-if="!q.required">（选填）</small></legend><template v-if="!['text','phone'].includes(q.type)"><label v-for="(o,j) in q.options" :key="o.id" class="psd-option" :class="{selected:isSelected(q,o.id)}"><input :type="q.type==='single'?'radio':'checkbox'" :name="q.id" :checked="isSelected(q,o.id)" @change="select(q,o.id)"/><span class="psd-check" :class="{square:q.type==='multiple'}"><Check v-if="isSelected(q,o.id)" :size="11"/></span><span class="option-text">{{String.fromCharCode(65+j)}}. {{o.text}}</span></label></template><div v-else-if="q.type==='phone'" class="phone-field"><input v-model="answers[q.id]" type="tel" inputmode="numeric" autocomplete="tel-national" maxlength="11" placeholder="请输入 11 位中国大陆手机号" aria-label="手机号，必填" @input="saveDraft"/><p>必填 · 仅用于本次问卷参与记录</p></div><textarea v-else v-model="answers[q.id]" :aria-label="q.title" rows="4" maxlength="2000" placeholder="请填写您的回答" @input="saveDraft"></textarea></fieldset><p v-if="error" class="error" role="alert">{{error}}</p><button class="psd-button" :disabled="busy">{{busy?'提交中…':'提交'}}</button><div class="survey-progress">已完成 {{progress}} / {{survey.questions.length}} 题 · 答案已自动暂存</div></form><img class="survey-footer" src="/assets/survey-footer.jpg" alt=""/></template>
      <template v-else-if="view==='success' && completion"><section class="psd-success"><h1>{{completion.heading}}</h1><div class="success-welcome"><p>{{completion.welcome}}</p><p>{{completion.venue}}</p></div><div class="success-sessions"><article v-for="session in completion.sessions"><p><Clock3 :size="20"/>{{session.time}}</p><h2>{{session.title}}</h2></article></div><p class="submitted-note"><Check :size="13"/>问卷已成功提交</p></section></template>
    </main><div v-if="privacy" class="modal-backdrop" @click.self="privacy=false"><section class="privacy-dialog modal" role="dialog" aria-modal="true" aria-labelledby="privacy-title" @keydown.esc="privacy=false"><h2 id="privacy-title">隐私说明</h2><p>版本：2026-11-02</p><p>本问卷在您同意后，通过微信登录获取 OpenID，用于识别参与身份和防止重复提交。您主动填写的昵称、选择的头像及问卷答案将用于参与记录与调查统计。</p><p>手机号由您在问卷中手动填写，作为必填项用于参与记录；不调用微信手机号授权。</p><p>资料仅供授权管理员查看和导出，不公开展示。您可以通过小程序反馈渠道联系运营方，申请查询、更正或删除资料。正式上线时以小程序《用户隐私保护指引》为准。</p><button class="primary" autofocus @click="privacy=false">我已了解</button></section></div>
  </div>
</template>
